import groupIcon from '@jetbrains/icons/group-12px'
import approvedIcon from '@jetbrains/icons/ok'
import inProgressIcon from '@jetbrains/icons/time'
import Avatar from '@jetbrains/ring-ui-built/components/avatar/avatar'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import plur from 'plur'
import * as React from 'react'
import {useContext} from 'react'
import {graphql, useFragment} from 'react-relay'

import {ApprovalStatuses} from '../../../services/rest'
import {notNull} from '../../../utils/guards'
import {Size} from '../Avatar/Avatar.container'
import AvatarRelay from '../Avatar/Avatar.relay'
import Badge from '../Badge/Badge'

import type {BuildApprovalReviewers_approvalGroups$key} from './__generated__/BuildApprovalReviewers_approvalGroups.graphql'
import type {BuildApprovalReviewers_approvalInfo$key} from './__generated__/BuildApprovalReviewers_approvalInfo.graphql'
import type {BuildApprovalReviewers_approvalUser$key} from './__generated__/BuildApprovalReviewers_approvalUser.graphql'
import type {
  BuildApprovalReviewers_compositeApproval$data,
  BuildApprovalReviewers_compositeApproval$key,
} from './__generated__/BuildApprovalReviewers_compositeApproval.graphql'
import type {BuildApprovalReviewers_compositeApprovals$key} from './__generated__/BuildApprovalReviewers_compositeApprovals.graphql'
import type {
  BuildApprovalReviewers_groupApproval$data,
  BuildApprovalReviewers_groupApproval$key,
} from './__generated__/BuildApprovalReviewers_groupApproval.graphql'
import type {BuildApprovalReviewers_groupedByStatusApprovals$key} from './__generated__/BuildApprovalReviewers_groupedByStatusApprovals.graphql'
import {BuildApprovalViewContext} from './BuildApproval.context'
import {useGroupedByStatusApprovals} from './BuildApproval.hooks'
import {BuildApprovalViewMode} from './BuildApproval.types'

import styles from './BuildApproval.module.css'

const approvalUserFragment = graphql`
  fragment BuildApprovalReviewers_approvalUser on User {
    name
    username
    id
    ...AvatarFragment
  }
`

type ApprovalUserProps = {
  userKey: BuildApprovalReviewers_approvalUser$key | null
  approved: boolean
  withAvatar: boolean
  showStatusIcon: boolean
  useUsernames: boolean
  showFrame: boolean
  style?: React.CSSProperties
}

function ApprovalUser({
  userKey,
  approved,
  withAvatar,
  showStatusIcon,
  useUsernames = false,
  showFrame = true,
  style = {},
}: ApprovalUserProps) {
  const user = useFragment(approvalUserFragment, userKey)
  const username = user?.username ?? `user_id:${user?.id}`
  const name = useUsernames ? username : (user?.name ?? username)

  const props = {
    popupProps: {top: -1, offset: 4},
    title: username,
  }
  const approvedStatusIcon = (
    <Tooltip title={approved ? 'Approved' : 'Awaiting approval'} delay={300} long>
      {approved ? <Icon glyph={approvedIcon} /> : <Icon glyph={inProgressIcon} />}
    </Tooltip>
  )

  const BadgeTag = showFrame ? Badge : React.Fragment
  const tagProps = showFrame ? {clickable: false, className: styles.approvalFrame} : {}
  return (
    <span
      style={{display: 'inline-flex', alignItems: 'center'}}
      className={approved ? styles.approved : styles.awaits}
    >
      <BadgeTag {...tagProps}>
        <span style={style}>
          {withAvatar ? (
            <Tooltip {...props}>
              {<AvatarRelay userKey={user} size={Size.Size20} withOutline={false} />}
            </Tooltip>
          ) : null}
          {<span>{name}</span>}
        </span>
      </BadgeTag>
      {showStatusIcon ? (
        <span className={styles.status} style={{marginLeft: '2px'}}>
          {approvedStatusIcon}
        </span>
      ) : null}
    </span>
  )
}

type ApprovalUserLineProps = {
  users: ReadonlyArray<BuildApprovalReviewers_approvalUser$key & {id?: number | null}>
  approved?: boolean
  withAvatar: boolean
  showStatusIcons: boolean
  useUsernames?: boolean
  useFrame?: boolean
}

function ApprovalUserLine(props: ApprovalUserLineProps) {
  if (props.users.length === 0) {
    return null
  }

  return <span style={{display: 'flex', gap: '4px'}}>{createApprovalUsers(props)}</span>
}

function createApprovalUsers({
  users,
  approved = false,
  withAvatar,
  showStatusIcons = false,
  useUsernames = false,
  useFrame = true,
}: ApprovalUserLineProps) {
  if (users.length === 0) {
    return []
  }

  return users.map(user => (
    <ApprovalUser
      key={`user:${user.id}`}
      userKey={user}
      approved={approved}
      withAvatar={withAvatar}
      showStatusIcon={showStatusIcons}
      useUsernames={useUsernames}
      showFrame={useFrame}
    />
  ))
}

type ApprovalUsersProps = {
  approvalsKey: BuildApprovalReviewers_groupedByStatusApprovals$key | null
  withAvatar: boolean
  buildApproved: boolean
}

function useApprovalUsers({approvalsKey, withAvatar, buildApproved}: ApprovalUsersProps) {
  const groupedApprovals = useGroupedByStatusApprovals(approvalsKey)

  const approvedUsers = createApprovalUsers({
    users: groupedApprovals.approved.map(({user}) => user).filter(notNull),
    approved: true,
    showStatusIcons: !buildApproved,
    withAvatar,
  })
  const nonApprovedUsers = createApprovalUsers({
    users: groupedApprovals.nonApproved.map(({user}) => user).filter(notNull),
    approved: false,
    showStatusIcons: !buildApproved,
    withAvatar,
  })
  return approvedUsers?.concat(nonApprovedUsers)
}

const groupApprovalFragment = graphql`
  fragment BuildApprovalReviewers_groupApproval on GroupApprovalRule {
    group {
      key
      name
    }
    requiredApprovalsCount
    currentlyApprovedBy {
      user {
        id
        ...BuildApprovalReviewers_approvalUser
      }
    }
  }
`

const compositeRuleFragment = graphql`
  fragment BuildApprovalReviewers_compositeApproval on CompositeApprovalRule {
    groups {
      key
      name
    }
    users {
      id
      ...BuildApprovalReviewers_approvalUser
    }
    requiredApprovalsCount
    currentlyApprovedBy {
      user {
        id
        ...BuildApprovalReviewers_approvalUser
      }
    }
  }
`

function CompositeApproval(props: {
  groupApprovalKey: BuildApprovalReviewers_groupApproval$key | null
  compositeApprovalKey: BuildApprovalReviewers_compositeApproval$key | null
  showStatusIcon: boolean
}) {
  let userRules
  let groupRules
  let approvalsRequired
  let approvedBy
  const groupPropsData: BuildApprovalReviewers_groupApproval$data | {} =
    useFragment(groupApprovalFragment, props.groupApprovalKey) ?? {}
  const compositePropsData: BuildApprovalReviewers_compositeApproval$data | {} =
    useFragment(compositeRuleFragment, props.compositeApprovalKey) ?? {}
  if (props.groupApprovalKey) {
    const groupProps = groupPropsData as BuildApprovalReviewers_groupApproval$data
    approvedBy = groupProps.currentlyApprovedBy?.user ?? []
    approvalsRequired = groupProps.requiredApprovalsCount ?? 0
    userRules = []
    groupRules = [groupProps.group]
  } else {
    const compositeProps = compositePropsData as BuildApprovalReviewers_compositeApproval$data
    userRules = compositeProps.users ?? []
    groupRules = compositeProps.groups ?? []
    approvalsRequired = compositeProps.requiredApprovalsCount ?? 0
    approvedBy = compositeProps.currentlyApprovedBy?.user ?? []
  }

  const approvalsLeft = Math.max((approvalsRequired ?? 0) - approvedBy.length, 0)
  const approvalsLeftMessage = (
    <span
      className={approvalsLeft > 0 ? styles.approvalsLeft : styles.groupApproved}
      style={{display: 'flex', marginLeft: '2px'}}
    >
      {`${approvedBy.length}/${approvalsRequired} ${plur('user', approvalsRequired)}`}{' '}
      {props.showStatusIcon && (
        <Icon
          style={{marginLeft: '2px'}}
          glyph={approvalsLeft > 0 ? inProgressIcon : approvedIcon}
        />
      )}
    </span>
  )

  const approvalsLeftElem = (
    <Tooltip
      title={
        <div>
          <span>
            {approvedBy.length > 0 && (
              <ApprovalUserLine
                approved
                users={approvedBy}
                withAvatar={false}
                showStatusIcons
                useUsernames
                useFrame={false}
              />
            )}
          </span>
          <div>
            {approvalsLeft > 0 &&
              `Awaiting ${approvalsLeft} more ${plur('approval', approvalsLeft)}`}
          </div>
        </div>
      }
      delay={300}
      long
    >
      {approvalsLeftMessage}
    </Tooltip>
  )

  const groupElem = groupRules.map(group => {
    const groupName = `${group?.name}`
    return [
      `groupName:${groupName}`,
      <span className={styles.group} key={`group:${group?.key}`}>
        <span>
          <Avatar info={<Icon style={{paddingTop: '4px'}} glyph={groupIcon} />} />
        </span>
        <span>{` ${groupName}`}</span>
      </span>,
    ]
  })

  const approvedUsersSet = new Set(approvedBy.map(user => user.id))
  const userElem = userRules.map(userKey => {
    const currentUserApproved = approvedUsersSet.has(userKey.id)
    return [
      `user:${userKey.id}`,
      <ApprovalUser
        key={userKey.id}
        userKey={userKey}
        approved={currentUserApproved}
        withAvatar
        showStatusIcon={currentUserApproved && props.showStatusIcon}
        useUsernames={false}
        showFrame={false}
      />,
    ]
  })

  const allElems = userElem.concat(groupElem)
  return (
    <span style={{display: 'flex', alignItems: 'center'}}>
      <Badge clickable={false} className={styles.approvalFrame}>
        {allElems.map(([elemKey, elem], index) => (
          <span key={`${elemKey}`}>
            {elem}
            {index === allElems.length - 1 ? null : (
              <span
                style={{
                  marginRight: '8px',
                  marginLeft: '8px',
                  color: 'var(--ring-secondary-color)',
                }}
              >
                {'|'}
              </span>
            )}
          </span>
        ))}
      </Badge>
      {approvalsLeftElem}
    </span>
  )
}

const approvalGroupsFragment = graphql`
  fragment BuildApprovalReviewers_approvalGroups on GroupApprovals {
    groupApproval {
      group {
        key
      }
      ...BuildApprovalReviewers_groupApproval
    }
  }
`

const approvalCompositeRulesFragment = graphql`
  fragment BuildApprovalReviewers_compositeApprovals on CompositeApprovals {
    compositeApproval {
      groups {
        key
      }
      users {
        id
      }
      requiredApprovalsCount
      ...BuildApprovalReviewers_compositeApproval
    }
  }
`

function useApprovalGroups({
  groupsApprovalsKey,
  compositeApprovalsKey,
  buildApproved,
}: {
  groupsApprovalsKey: BuildApprovalReviewers_approvalGroups$key | null
  compositeApprovalsKey: BuildApprovalReviewers_compositeApprovals$key | null
  buildApproved: boolean
}) {
  const groupsApprovals =
    useFragment(approvalGroupsFragment, groupsApprovalsKey)?.groupApproval ?? []
  const compositeApprovals =
    useFragment(approvalCompositeRulesFragment, compositeApprovalsKey)?.compositeApproval ?? []
  const groupApprovalsElems = groupsApprovals.map(approval => (
    <CompositeApproval
      key={`group:${approval.group?.key}`}
      groupApprovalKey={approval}
      compositeApprovalKey={null}
      showStatusIcon={!buildApproved}
    />
  ))
  const compositeApprovalsElems = compositeApprovals.map(approval => {
    const key = `composite:${approval.groups?.map(group => `group:${group.key}`).join(',')},
                             ${approval.users?.map(user => `user:${user.id}`).join(',')}:${approval.requiredApprovalsCount}`
    return (
      <CompositeApproval
        key={key}
        groupApprovalKey={null}
        compositeApprovalKey={approval}
        showStatusIcon={!buildApproved}
      />
    )
  })
  return groupApprovalsElems.concat(compositeApprovalsElems)
}

const fragment = graphql`
  fragment BuildApprovalReviewers_approvalInfo on ApprovalInfo {
    userApprovals {
      ...BuildApprovalReviewers_groupedByStatusApprovals
    }
    groupApprovals {
      ...BuildApprovalReviewers_approvalGroups
    }
    compositeApprovals {
      ...BuildApprovalReviewers_compositeApprovals
    }
    status
  }
`

type ApprovalProps = {
  approvalInfoKey: BuildApprovalReviewers_approvalInfo$key | null
}

export default function BuildApprovalReviewers({approvalInfoKey}: ApprovalProps) {
  const {
    userApprovals = null,
    groupApprovals = null,
    compositeApprovals = null,
    status,
  } = useFragment(fragment, approvalInfoKey) ?? {}
  const view = useContext(BuildApprovalViewContext)
  const buildApproved = status === ApprovalStatuses.APPROVED
  const elems = useApprovalUsers({
    approvalsKey: userApprovals,
    withAvatar: true,
    buildApproved,
  }).concat(
    useApprovalGroups({
      groupsApprovalsKey: groupApprovals,
      compositeApprovalsKey: compositeApprovals,
      buildApproved,
    }),
  )

  return (
    <div
      className={classNames({
        [styles.inline]: view === BuildApprovalViewMode.INLINE,
        [styles.popup]: view === BuildApprovalViewMode.POPUP,
      })}
    >
      {elems}
    </div>
  )
}
